CREATE TABLE public.pages (
    page_id text NOT NULL,
    doc_id text NOT NULL,
    page_no integer NOT NULL,
    raw text NOT NULL,
    section text DEFAULT ''::text NOT NULL
);


--
-- Name: doc_texts; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.doc_texts AS
 SELECT doc_id,
    string_agg(public.kkey(raw), ''::text ORDER BY page_no) AS hay
   FROM public.pages
  GROUP BY doc_id
  WITH NO DATA;


--
-- Name: documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documents (
    doc_id text NOT NULL,
    society text NOT NULL,
    year integer NOT NULL
);


--
-- Name: edition_changes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.edition_changes (
    old_doc text NOT NULL,
    new_doc text NOT NULL,
    section text NOT NULL,
    kind text NOT NULL,
    notation text NOT NULL,
    old_pages text NOT NULL,
    new_pages text NOT NULL,
    old_req text NOT NULL,
    new_req text NOT NULL,
    CONSTRAINT edition_changes_kind_check CHECK ((split_part(kind, ' ('::text, 1) = ANY (ARRAY['신설'::text, '삭제'::text, '명칭 변경'::text, '요건 변경'::text])))
);


--
-- Name: edition_change_pages; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.edition_change_pages AS
 SELECT DISTINCT ((d.doc || ':'::text) || p.p) AS page_id,
    split_part(d.kind, ' ('::text, 1) AS kind
   FROM ( SELECT edition_changes.old_doc AS doc,
            edition_changes.kind,
            edition_changes.old_pages AS pg
           FROM public.edition_changes
        UNION ALL
         SELECT edition_changes.new_doc,
            edition_changes.kind,
            edition_changes.new_pages
           FROM public.edition_changes) d,
    LATERAL unnest(string_to_array(NULLIF(d.pg, ''::text), ' '::text)) p(p);


